def documents():
    raw = json.loads(zlib.decompress(base64.b85decode(FIXTURE)))
    return {
        role: body if role == "initial_native_log" else receiver.document(body.encode())
        for role, body in raw.items()
    }


def refresh(docs, *, align=True):
    """Repair outer commitments to reach each authored semantic boundary."""

    def pin(role):
        body = (
            docs[role].encode() if role == "initial_native_log" else receiver.canonical(docs[role])
        )
        return {
            "path": "/authored/" + role + ".json",
            "sha256": sha256(body).hexdigest(),
            "size_bytes": len(body),
        }

    for prefix in ("initial", "selected"):
        freeze = docs[prefix + "_execution_freeze"]
        freeze["source_evolution_sha256"] = pin("source_evolution")["sha256"]
        freeze["test_source_evolution_sha256"] = pin("test_source_evolution")["sha256"]
        if prefix == "selected":
            freeze["benchmark_source_evolution_sha256"] = pin("benchmark_source_evolution")[
                "sha256"
            ]
            freeze["static_preflight_sha256"] = pin("selected_preflight")["sha256"]
        docs[prefix + "_native_command_result"]["freeze_sha256"] = pin(
            prefix + "_execution_freeze"
        )["sha256"]
    native = docs["native_result"]
    audits = (
        ("native_requests", "request"),
        ("native_invocations", "invocation"),
        ("native_launches", "launch"),
        ("native_live_processes", "live"),
        ("native_lifecycles", "lifecycle"),
    )
    for role, field in audits:
        native["audit_sha256"][receiver.ARTIFACT_KEYS[role].rsplit("/", 1)[-1]] = pin(role)[
            "sha256"
        ]
        if align and len(docs[role]) == 6:
            for index, case in enumerate(native["kernel_cases"] + native["transport_cases"]):
                case["native"][field] = copy.deepcopy(docs[role][index])
    docs["preservation_before"]["qualifications"][
        "registry-operation-budget-qualification-20261003"
    ]["qualification_sha256"] = pin("prior_registry_qualification")["sha256"]
    for role, key in receiver.ARTIFACT_KEYS.items():
        docs["qualification"]["artifact_sha256"][key] = pin(role)["sha256"]
    return {role: pin(role) for role in receiver.ROLES}


def replace(docs, path, value):
    obj = docs
    for part in path[:-1]:
        obj = obj[part]
    obj[path[-1]] = value


class MetadataControls(unittest.TestCase):
    def test_duplicate_pid_refused_after_live_and_nested_bindings_repaired(self):
        docs = documents()
        duplicate = docs["native_lifecycles"][0]["result"]["pid"]
        docs["native_lifecycles"][1]["result"]["pid"] = duplicate
        docs["native_live_processes"][1]["pid"] = duplicate
        pins = refresh(docs)
        with self.assertRaisesRegex(ValueError, "distinct lifecycle"):
            receiver.derive(docs, pins)

    def test_cpu_rounding_refused_with_original_invocation_suffix_preserved(self):
        docs = documents()
        argv = docs["native_launches"][4]["argv"]
        index = argv.index("--cpu=1:1")
        argv[index] = "--cpu=2:2"
        pins = refresh(docs)
        with self.assertRaisesRegex(ValueError, "OS-rounded CPU"):
            receiver.derive(docs, pins)

    def test_nonfinite_remaining_refused_before_arithmetic(self):
        docs = documents()
        docs["native_invocations"][0]["remaining_seconds"] = float("inf")
        with self.assertRaisesRegex(ValueError, "finite recorded observation"):
            receiver.phase_observations(docs, docs["native_result"])

    def test_baseline_separates_kernel_completion_and_python_transport_stops(self):
        docs = documents()
        result = receiver.derive(docs, refresh(docs))
        self.assertEqual(len(result["phase_observations"]), 6)
        self.assertEqual(len(result["kernel_cases"]), 4)
        self.assertEqual(len(result["transport_controls"]), 2)
        timeout, cancel = result["transport_controls"]
        self.assertEqual(timeout["recorded_attempt_status"], "timed_out")
        self.assertTrue(timeout["recorded_native_timed_out"])
        self.assertTrue(timeout["recorded_native_cancelled"])
        self.assertEqual(cancel["recorded_attempt_status"], "cancelled")
        self.assertFalse(cancel["recorded_native_timed_out"])
        self.assertTrue(cancel["owned_child_observed_alive_before_cancel"])
        self.assertTrue(
            all(x["kernel_interruption_exercised"] is False for x in result["kernel_cases"])
        )
        self.assertEqual(result["production_tasks_closed"], [])

    def test_cpu_ceiling_rounding_preserves_unchanged_two_second_cancel_ceiling(self):
        docs = documents()
        result = receiver.derive(docs, refresh(docs))
        phases = result["phase_observations"]
        self.assertEqual(phases[0]["recorded_rounded_cpu_seconds"], 15)
        self.assertLess(phases[0]["recorded_effective_cpu_seconds"], 15)
        self.assertEqual(phases[4]["recorded_rounded_cpu_seconds"], 1)
        self.assertLess(phases[4]["recorded_effective_cpu_seconds"], 1)
        self.assertEqual(phases[5]["recorded_effective_cpu_seconds"], 2)
        self.assertGreater(phases[5]["recorded_remaining_seconds"], 2)

    def test_failed_and_unaccepted_attempts_remain_distinct(self):
        docs = documents()
        result = receiver.derive(docs, refresh(docs))
        history = result["attempt_history"]
        self.assertEqual(
            [x["accepted"] for x in history["test_attempts"]], [False, False, False, True, True]
        )
        self.assertEqual(
            history["test_attempts"][0]["recorded_counts"], {"passed": 809, "failure": 9}
        )
        self.assertEqual([x["recorded_returncode"] for x in history["native_attempts"]], [1, 0])
        self.assertFalse(
            history["native_attempts"][0]["before_pool_or_execution_independently_attested"]
        )
        self.assertEqual(result["test_population"]["new_inheritance_case_count"], 58)
        self.assertEqual(result["test_population"]["additional_existing_case_count"], 41)
        self.assertFalse(result["test_population"]["test_counts_summed"])

    def test_raw_stop_flags_survive_rebound_timing_and_generic_accounting(self):
        docs = documents()
        case = docs["native_result"]["transport_cases"][0]
        self.assertEqual(case["result"]["usage"]["elapsed_ms"], 1000)
        self.assertGreater(case["native"]["lifecycle"]["result"]["elapsed_seconds"], 1)
        result = receiver.derive(docs, refresh(docs))
        self.assertFalse(result["transport_controls"][0]["native_solver_cancellation_requalified"])
        self.assertFalse(
            result["source_preservation"]["source_assertions_or_diff_semantics_verified"]
        )


