def mutation_control(name, path, value):
    def test(self):
        docs = documents()
        obj = docs
        for part in path[:-1]:
            obj = obj[part]
        self.assertIn(path[-1], obj)
        replace(docs, path, copy.deepcopy(value))
        with self.assertRaises((ValueError, KeyError, TypeError)):
            receiver.derive(docs, refresh(docs))

    return test


for name, path, value in MUTATIONS:
    setattr(MetadataControls, "test_refuse_" + name, mutation_control(name, path, value))


def overwrite(path, raw):
    path.chmod(0o600)
    path.write_bytes(raw)


class FileControls(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name).resolve()
        self.input = self.root / "input.json"
        self.output = self.root / "output"
        raw = json.loads(zlib.decompress(base64.b85decode(FIXTURE)))
        rows = []
        for role in receiver.ROLES:
            path = self.root / (role + ".json")
            body = raw[role].encode()
            path.write_bytes(body)
            rows.append(
                {
                    "role": role,
                    "path": str(path),
                    "sha256": sha256(body).hexdigest(),
                    "size_bytes": len(body),
                }
            )
        self.manifest = {
            "schema": receiver.INPUT_SCHEMA,
            "selected_profile": receiver.PROFILE,
            "selected_files": rows,
        }
        self.save_manifest()

    def save_manifest(self):
        self.input.write_bytes(receiver.canonical(self.manifest))

    def test_full_standalone_writer_and_typed_scopes(self):
        report = receiver.audit(self.input, self.output)
        self.assertTrue(report["qualified"])
        self.assertEqual(report["selected_file_count"], 27)
        self.assertEqual(report["custody"]["original_file_count"], 28)
        self.assertEqual(report["custody"]["copy_file_count"], 28)
        self.assertEqual(len([p for p in self.output.rglob("*") if p.is_file()]), 30)
        nested = receiver.document((self.output / "selected_custody.json").read_bytes())
        self.assertEqual(nested["scope"], report["scope"])
        self.assertEqual(report["scope"], receiver.scope())
        self.assertEqual(nested["production_tasks_closed"], [])
        for index, role in enumerate(receiver.ROLES):
            self.assertEqual(report[role + "_sha256"], report["selected_files"][index]["sha256"])
        self.assertEqual(
            receiver.document(
                (self.output / "native_operation_inheritance_custody.json").read_bytes()
            ),
            report,
        )

    def test_explicit_full_physical_relocation(self):
        target = self.root / "relocated"
        target.mkdir()
        remap = {}
        for index, logical in enumerate(
            [self.input, *[Path(row["path"]) for row in self.manifest["selected_files"]]]
        ):
            physical = target / f"{index}.json"
            physical.write_bytes(logical.read_bytes())
            remap[str(logical)] = str(physical)
            logical.unlink()
        self.assertTrue(
            receiver.audit(self.input, self.output, relocated_sources=remap)["qualified"]
        )

    def test_manifest_role_reordering(self):
        self.manifest["selected_files"].reverse()
        self.save_manifest()
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_input_raw_mutation(self):
        Path(self.manifest["selected_files"][0]["path"]).write_bytes(b"{}")
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_caller_rebound_public_selection_refused(self):
        row = self.manifest["selected_files"][0]
        body = b"{}"
        Path(row["path"]).write_bytes(body)
        row.update(sha256=sha256(body).hexdigest(), size_bytes=len(body))
        self.save_manifest()
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_selected_symlink_refused(self):
        path = Path(self.manifest["selected_files"][0]["path"])
        alternate = self.root / "body.json"
        path.rename(alternate)
        path.symlink_to(alternate)
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_hardlink_alias_refused(self):
        path = self.root / "a.json"
        path.write_bytes(b"{}")
        alias = self.root / "b.json"
        os.link(path, alias)
        cache = receiver.Capture()
        cache.read(path)
        with self.assertRaises(ValueError):
            cache.read(alias)

    def test_fifo_does_not_block(self):
        path = self.root / "fifo"
        os.mkfifo(path)
        with self.assertRaises(ValueError):
            receiver.Capture.raw(path, 1024)

    def test_partial_relocation_refused(self):
        with self.assertRaises(ValueError):
            receiver.audit(
                self.input, self.output, relocated_sources={str(self.input): str(self.input)}
            )

    def test_reused_output_refused(self):
        self.output.mkdir()
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_size_bool_refused(self):
        self.manifest["selected_files"][0]["size_bytes"] = True
        self.save_manifest()
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)

    def test_aggregate_preallocation_refused(self):
        with patch.object(receiver, "MAX_BYTES", 1024):
            with self.assertRaises(ValueError):
                receiver.audit(self.input, self.output)
        self.assertFalse(self.output.exists())

    def test_declared_file_cap_refused(self):
        self.manifest["selected_files"][0]["size_bytes"] = receiver.MAX_FILE + 1
        self.save_manifest()
        with self.assertRaises(ValueError):
            receiver.audit(self.input, self.output)
        self.assertFalse(self.output.exists())

    def late_change(self, action):
        original = receiver.write_new

        def write(path, raw):
            original(path, raw)
            if path.name == "native_operation_inheritance_custody.json":
                action(path)

        with patch.object(receiver, "write_new", write):
            with self.assertRaises((ValueError, FileNotFoundError)):
                receiver.audit(self.input, self.output)

    def test_late_input_byte_change(self):
        self.late_change(lambda _: self.input.write_bytes(b"{}"))

    def test_late_identical_input_inode_replacement(self):
        def alter(_):
            raw = self.input.read_bytes()
            self.input.unlink()
            self.input.write_bytes(raw)

        self.late_change(alter)

    def test_late_copy_byte_change(self):
        self.late_change(lambda _: overwrite(self.output / "retained/input.json", b"{}"))

    def test_late_nested_scope_change(self):
        def alter(_):
            path = self.output / "selected_custody.json"
            value = receiver.document(path.read_bytes())
            value["scope"]["native_execution_performed"] = True
            overwrite(path, receiver.canonical(value))

        self.late_change(alter)

    def test_late_main_count_type_change(self):
        def alter(path):
            value = receiver.document(path.read_bytes())
            value["runtime_fact_count"] = False
            overwrite(path, receiver.canonical(value))

        self.late_change(alter)

    def test_late_extra_file(self):
        self.late_change(lambda _: (self.output / "extra.json").write_bytes(b"{}"))

    def test_late_extra_directory(self):
        self.late_change(lambda _: (self.output / "extra").mkdir())

    def test_late_symlink_receipt(self):
        def alter(path):
            raw = path.read_bytes()
            path.unlink()
            alternative = self.root / "alternative.json"
            alternative.write_bytes(raw)
            path.symlink_to(alternative)

        self.late_change(alter)

    def test_json_duplicate_keys(self):
        with self.assertRaises(ValueError):
            receiver.document(b'{"x":0,"x":1}')

    def test_json_nonfinite(self):
        with self.assertRaises(ValueError):
            receiver.document(b'{"x":NaN}')

    def test_json_deep_array_allocation(self):
        with self.assertRaises(ValueError):
            receiver.document(b"[" * 34 + b"0" + b"]" * 34)

    def test_json_lone_surrogate(self):
        with self.assertRaises(ValueError):
            receiver.document(b'{"x":"\\ud800"}')

    def test_report_preallocation_cap(self):
        with patch.object(receiver, "MAX_REPORT", 8):
            with self.assertRaises(ValueError):
                receiver.audit(self.input, self.output)
        self.assertFalse((self.output / "selected_custody.json").exists())

    def closing_change(self, ordinal, kind):
        population = receiver.output_population
        calls = 0

        def walk(root, expected):
            nonlocal calls
            population(root, expected)
            calls += 1
            if calls == ordinal:
                if kind == "original":
                    self.input.write_bytes(b"{}")
                elif kind == "copy":
                    overwrite(root / "retained/input.json", b"{}")
                elif kind == "main":
                    overwrite(root / "native_operation_inheritance_custody.json", b"{}")
                elif kind == "nested":
                    overwrite(root / "selected_custody.json", b"{}")
                elif kind == "extra":
                    (root / "extra.json").write_bytes(b"{}")
                elif kind == "alias":
                    (root / "alias.json").symlink_to(root / "selected_custody.json")
                else:
                    path = root / "selected_custody.json"
                    raw = path.read_bytes()
                    path.unlink()
                    path.write_bytes(raw)

        with patch.object(receiver, "output_population", walk):
            with self.assertRaises((ValueError, FileNotFoundError)):
                receiver.audit(self.input, self.output)
        self.assertGreaterEqual(calls, ordinal)


def closing_control(ordinal, kind):
    def test(self):
        self.closing_change(ordinal, kind)

    return test


for closing_ordinal in (1, 2):
    for closing_kind in ("original", "copy", "main", "nested", "extra", "alias", "inode"):
        setattr(
            FileControls,
            f"test_closing_pass_{closing_ordinal}_{closing_kind}",
            closing_control(closing_ordinal, closing_kind),
        )


if __name__ == "__main__":
    unittest.main()
